	gtk.OSMemmoveOverload12(&klass, g_class)
	gtk.OSCallFunctionArg0Arg1Arg2Arg3(klass.Get_preferred_width, cell, handle, minimun_size, natural_size)
	this.SendMeasureEvent(cell, minimun_size, int64(0))
